import { Component, ElementRef, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { ActivatedRouteSnapshot, NavigationEnd, Router, RouterOutlet } from '@angular/router';
import { DatePipe, NgClass } from '@angular/common';
import { Subscription } from 'rxjs';
import { AppNotification, NotificationService } from './services/notification.service';
import { NotificationTypeLabelPipe } from './services/notification-type-label.pipe';
import { AuthService } from './services/auth.service';
import { DataService } from './services/data.service';
import {
  FirestorePortalNotificationsService,
  type PortalNotificationRow,
} from './services/firestore-portal-notifications.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet, NgClass, DatePipe, NotificationTypeLabelPipe],
  template: `
    <router-outlet></router-outlet>

    @if (showGlobalUi) {
      <div class="global-notifications">
        <button
          class="global-notifications__bell"
          type="button"
          (click)="toggleNotifications()"
          [attr.aria-label]="'Notifications'"
          [attr.aria-expanded]="showNotifications"
        >
          <svg
            class="global-notifications__icon"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.8"
            stroke-linecap="round"
            stroke-linejoin="round"
            aria-hidden="true"
          >
            <path d="M12 3a5 5 0 0 0-5 5v2.5c0 .7-.2 1.4-.6 2l-.8 1.2A1 1 0 0 0 6.4 15h11.2a1 1 0 0 0 .8-1.3l-.8-1.2c-.4-.6-.6-1.3-.6-2V8a5 5 0 0 0-5-5Z" />
            <path d="M10 18a2 2 0 0 0 4 0" />
          </svg>
          @if (unreadCount > 0) {
            <span class="global-notifications__badge">{{ unreadCount > 9 ? '9+' : unreadCount }}</span>
          }
        </button>

        @if (showNotifications) {
          <button
            class="global-notifications__backdrop"
            type="button"
            (click)="closeNotifications()"
            [attr.aria-label]="'Close notifications'"
            tabindex="-1"
          ></button>
          <div
            class="global-notifications__panel"
            role="dialog"
            [attr.aria-label]="'Notifications'"
            (click)="$event.stopPropagation()"
          >
            <div class="global-notifications__panelHeader">
              <span class="global-notifications__panelTitle">Notifications</span>
              @if (notifications.length) {
                <button
                  class="global-notifications__markAll"
                  type="button"
                  (click)="markAllAsRead()"
                >
                  Mark all as read
                </button>
              }
              <button
                class="global-notifications__close"
                type="button"
                (click)="closeNotifications()"
                [attr.aria-label]="'Close notifications'"
              >
                ✕
              </button>
            </div>
            <div class="global-notifications__panelBody">
              @if (!notifications.length) {
                <p class="global-notifications__empty">No notifications yet.</p>
              } @else {
                @if (showLatestButton) {
                  <div class="global-notifications__topAction">
                    <button
                      class="global-notifications__showLatest"
                      type="button"
                      (click)="showLatestNotifications()"
                    >
                      Show latest notification
                    </button>
                  </div>
                }
                <ul class="global-notifications__list" #notificationsList (scroll)="onNotificationsScroll()">
                  @for (n of notifications; track n.id) {
                    <li
                      class="global-notifications__item"
                      [ngClass]="{
                        'global-notifications__item--unread': !n.read,
                        'global-notifications__item--type-success': n.type === 'success',
                        'global-notifications__item--type-error': n.type === 'error',
                        'global-notifications__item--type-warning': n.type === 'warning',
                        'global-notifications__item--type-info': n.type === 'info',
                        'global-notifications__item--hasRoute': notificationHasRequestLink(n)
                      }"
                      (click)="onNotificationClick(n, $event)"
                    >
                      <div class="global-notifications__itemHeader">
                        <span class="global-notifications__itemTitle">
                          {{ n.title || (n.type | notificationTypeLabel) }}
                        </span>
                        <span class="global-notifications__itemTime">
                          {{ n.createdAt | date: 'shortTime' }}
                        </span>
                      </div>
                      <p class="global-notifications__itemMessage">
                        {{ n.message }}
                      </p>
                    </li>
                  }
                </ul>
              }
            </div>
          </div>
        }
      </div>
    }
  `,
  styles: [
    `
      :host {
        display: block;
      }

      .global-notifications {
        position: fixed;
        top: 14px; /* centered in 72px top bar: (72 - 44) / 2 */
        right: 76px; /* left of profile icon (24 + 44 + 8) */
        z-index: 1100;
        isolation: isolate;
        transition: transform 0.3s ease-out, filter 0.3s ease-out;
        
        @media (max-width: 640px) {
          top: 12px; /* centered in 68px bar */
          right: 68px; /* 20 + 40 + 8 */
        }
      }

      /* When the sidebar drawer is open on laptop/mobile, disable + blur the bell
         so it can't be clicked (but remains visible for context). */
      :host-context(body.sidebar-open) .global-notifications {
        filter: blur(2px);
        -webkit-filter: blur(2px);
        opacity: 0.45; /* disabled but more readable */
        pointer-events: none;
        z-index: 999; /* keep visible (but still below the drawer) */
      }

      .global-notifications__bell {
        position: relative;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 44px;
        height: 44px;
        border: 1px solid var(--color-border);
        border-radius: 9999px;
        background: var(--color-bg-card);
        color: var(--color-text);
        box-shadow: var(--shadow-lg);
        cursor: pointer;
        transition: background 0.2s ease, transform 0.2s ease, box-shadow 0.25s ease, border-color 0.2s ease;
        
        @media (max-width: 640px) {
          width: 40px;
          height: 40px;
        }
      }

      .global-notifications__bell:hover {
        background: var(--color-bg);
        box-shadow: var(--shadow-lg), 0 0 0 2px var(--color-border);
        transform: scale(1.06);
        border-color: var(--color-text-muted, rgba(0, 0, 0, 0.2));
      }

      .global-notifications__bell:active {
        transform: scale(0.97);
        box-shadow: var(--shadow);
      }

      /* When SweetAlert2 is open (e.g. logout confirm), remove focus/hover highlight from bell */
      :host-context(body.swal2-shown) .global-notifications__bell:hover,
      :host-context(body.swal2-shown) .global-notifications__bell:focus,
      :host-context(body.swal2-shown) .global-notifications__bell:focus-visible {
        outline: none;
        box-shadow: var(--shadow-lg);
        transform: scale(1);
        border-color: var(--color-border);
        background: var(--color-bg-card);
      }
      
      :host-context(body.swal2-shown) .global-notifications__bell {
        color: var(--color-text-muted) !important;
      }

      .global-notifications__icon {
        width: 22px;
        height: 22px;
        flex-shrink: 0;
        display: block;
        transform: translateY(1px);
        
        @media (max-width: 640px) {
          width: 20px;
          height: 20px;
        }
      }

      .global-notifications__badge {
        position: absolute;
        top: 0;
        right: 0;
        transform: translate(35%, -35%);
        min-width: 18px;
        padding: 2px 6px;
        border-radius: 9999px;
        background: var(--color-warning);
        color: #fff;
        font-size: 0.75rem;
        font-weight: 700;
        text-align: center;
        line-height: 1.4;
        box-shadow: var(--shadow);
      }

      .global-notifications__panel {
        position: absolute;
        top: 52px;
        right: 0;
        /* Keep a stable width (avoid min()/dvw edge cases that can cause narrow panels) */
        width: 360px;
        max-width: calc(100vw - 32px);
        background: var(--color-bg-card);
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow-lg);
        overflow: hidden;
        max-height: calc(100vh - 32px);
        z-index: 2;
        animation: globalNotificationsPanelIn 0.18s ease-out;
        display: flex;
        flex-direction: column;

        @media (max-width: 640px) {
          /* topbar height on mobile is 68px; keep panel below it (with small gap) */
          top: 72px;
          /* Anchor to viewport to prevent awkward offsets on mobile */
          position: fixed;
          left: 12px;
          right: 12px;
          width: auto;
          max-width: none;
          max-height: calc(100vh - 64px);
        }
      }

      @keyframes globalNotificationsPanelIn {
        from {
          opacity: 0;
          transform: translateY(-4px) scale(0.98);
        }
        to {
          opacity: 1;
          transform: translateY(0) scale(1);
        }
      }

      .global-notifications__panelHeader {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 12px 14px;
        border-bottom: 1px solid var(--color-border);
      }

      .global-notifications__panelTitle {
        font-weight: 600;
        color: var(--color-text);
      }

      .global-notifications__markAll {
        margin-left: auto;
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 6px 12px;
        border-radius: 9999px;
        border: 1px solid transparent;
        background: transparent;
        color: var(--color-primary, #2563eb);
        font-size: 0.8125rem;
        font-weight: 500;
        cursor: pointer;
        transition:
          background-color 0.15s ease,
          border-color 0.15s ease,
          color 0.15s ease,
          transform 0.05s ease;
      }

      .global-notifications__markAll:hover {
        background: color-mix(in srgb, var(--color-primary, #2563eb) 8%, transparent);
        border-color: color-mix(in srgb, var(--color-primary, #2563eb) 35%, transparent);
      }

      .global-notifications__markAll:active {
        transform: translateY(1px);
      }

      .global-notifications__markAll:focus-visible {
        outline: 2px solid color-mix(in srgb, var(--color-primary, #2563eb) 65%, transparent);
        outline-offset: 2px;
      }

      .global-notifications__close {
        border: none;
        background: transparent;
        cursor: pointer;
        border-radius: var(--radius);
        padding: 6px 8px;
        color: var(--color-text-muted);
      }

      .global-notifications__close:hover {
        background: var(--color-bg);
        color: var(--color-text);
      }

      .global-notifications__panelBody {
        flex: 1;
        min-height: 0;
        padding: 12px 14px;
        background: linear-gradient(
          180deg,
          color-mix(in srgb, var(--color-bg-card) 92%, transparent),
          color-mix(in srgb, var(--color-bg) 100%, transparent)
        );
        display: flex;
        flex-direction: column;
      }

      .global-notifications__empty {
        margin: 8px 0 4px;
        color: var(--color-text-muted);
        font-size: 0.9375rem;
        text-align: center;
      }

      .global-notifications__topAction {
        display: flex;
        justify-content: center;
        margin: 0 0 8px;
      }

      .global-notifications__showLatest {
        border: 1px solid color-mix(in srgb, var(--color-primary, #2563eb) 30%, transparent);
        background: color-mix(in srgb, var(--color-primary, #2563eb) 8%, transparent);
        color: var(--color-primary, #2563eb);
        font-size: 0.8125rem;
        font-weight: 600;
        cursor: pointer;
        padding: 6px 12px;
        border-radius: 9999px;
      }

      .global-notifications__showLatest:hover {
        background: color-mix(in srgb, var(--color-primary, #2563eb) 14%, transparent);
      }

      .global-notifications__list {
        list-style: none;
        margin: 0;
        padding: 4px 0;
        max-height: 520px;
        overflow-y: auto;
        flex: 1;
        min-height: 0;
        scrollbar-width: none; /* Firefox */
        -ms-overflow-style: none; /* IE and legacy Edge */
      }

      .global-notifications__list::-webkit-scrollbar {
        width: 0;
        height: 0;
        display: none; /* Chrome, Safari, Opera */
      }

      .global-notifications__item {
        position: relative;
        padding: 10px 12px 9px 16px;
        margin-bottom: 6px;
        border-radius: calc(var(--radius) - 1px);
        border: 1px solid color-mix(in srgb, var(--color-border) 80%, transparent);
        border-left-width: 3px;
        border-left-style: solid;
        border-left-color: transparent;
        background: color-mix(in srgb, var(--color-bg-card) 92%, transparent);
        box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
        cursor: pointer;
        transition:
          background 0.16s ease,
          border-color 0.16s ease,
          box-shadow 0.16s ease,
          transform 0.08s ease;
      }

      .global-notifications__item:hover {
        background: color-mix(in srgb, var(--color-bg-card) 98%, transparent);
        box-shadow: 0 3px 10px rgba(15, 23, 42, 0.08);
        transform: translateY(-1px);
      }

      .global-notifications__item--unread {
        background: color-mix(in srgb, var(--color-primary-bg, #eff6ff) 85%, transparent);
        border-color: color-mix(in srgb, var(--color-primary, #2563eb) 40%, var(--color-border) 60%);
        box-shadow: 0 4px 14px rgba(37, 99, 235, 0.22);
      }

      .global-notifications__item--unread::before {
        content: '';
        position: absolute;
        left: 8px;
        top: 16px;
        width: 8px;
        height: 8px;
        border-radius: 999px;
        background: var(--color-primary);
        box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-primary, #2563eb) 20%, transparent);
      }

      .global-notifications__itemHeader {
        display: flex;
        align-items: baseline;
        gap: 6px;
        margin-bottom: 4px;
      }

      .global-notifications__itemTitle {
        font-weight: 600;
        font-size: 0.9rem;
        color: var(--color-text);
        flex: 1;
        min-width: 0;
        white-space: nowrap;
        text-overflow: ellipsis;
        overflow: hidden;
      }

      .global-notifications__itemTime {
        font-size: 0.75rem;
        color: var(--color-text-muted);
        flex-shrink: 0;
      }

      .global-notifications__itemMessage {
        margin: 0;
        font-size: 0.85rem;
        line-height: 1.4;
        color: var(--color-text-muted);
      }

      .global-notifications__item--type-success {
        border-left-color: var(--color-success);
      }

      .global-notifications__item--type-error {
        border-left-color: #dc2626;
      }

      .global-notifications__item--type-warning {
        border-left-color: var(--color-warning);
      }

      .global-notifications__item--type-info {
        border-left-color: var(--color-primary);
      }

      .global-notifications__item--hasRoute .global-notifications__itemTitle::after {
        content: ' →';
        font-weight: 500;
        color: var(--color-primary, #2563eb);
      }

      .global-notifications__backdrop {
        position: fixed;
        inset: 0;
        background: transparent;
        border: none;
        cursor: default;
        z-index: 1;
        padding: 0;
        margin: 0;
      }
    `,
  ],
})
export class AppComponent implements OnInit, OnDestroy {
  @ViewChild('notificationsList') notificationsListRef?: ElementRef<HTMLUListElement>;
  unreadCount = 0;
  showNotifications = false;
  showGlobalUi = false;
  notifications: AppNotification[] = [];
  showLatestButton = false;

  private notificationsSub?: Subscription;
  private residentsDataSub?: Subscription;
  private firestorePortalSub?: Subscription;
  private firestoreBellBindKey = '';

  constructor(
    private router: Router,
    private notificationsService: NotificationService,
    private auth: AuthService,
    private data: DataService,
    private firestorePortal: FirestorePortalNotificationsService,
  ) {
    this.router.events.subscribe(event => {
      if (event instanceof NavigationEnd) {
        this.updateGlobalUi(event.urlAfterRedirects);
        this.refreshNotifications();
      }
    });
  }

  ngOnInit(): void {
    this.notificationsSub = this.notificationsService.notifications$.subscribe(() => {
      this.refreshNotifications();
    });
    this.residentsDataSub = this.data.residentsObservable.subscribe(() => {
      this.refreshNotifications();
    });
    this.refreshNotifications();
  }

  ngOnDestroy(): void {
    this.notificationsSub?.unsubscribe();
    this.residentsDataSub?.unsubscribe();
    this.firestorePortalSub?.unsubscribe();
  }

  toggleNotifications() {
    this.showNotifications = !this.showNotifications;
    if (!this.showNotifications) {
      this.showLatestButton = false;
    }
  }

  closeNotifications() {
    this.showNotifications = false;
    this.showLatestButton = false;
  }

  showLatestNotifications(): void {
    this.notificationsListRef?.nativeElement.scrollTo({ top: 0, behavior: 'smooth' });
    this.showLatestButton = false;
  }

  onNotificationsScroll(): void {
    const scrollTop = this.notificationsListRef?.nativeElement.scrollTop ?? 0;
    this.showLatestButton = scrollTop > 80;
  }

  markAsRead(id: string) {
    this.notificationsService.markAsRead(id);
  }

  notificationHasRequestLink(n: AppNotification): boolean {
    return !!(
      n.linkRequestId?.trim() ||
      (n.actionRoute?.length === 2 && n.actionRoute[0] === 'requests') ||
      this.parseRequestIdFromMessage(n.message)
    );
  }

  onNotificationClick(n: AppNotification, ev?: Event): void {
    ev?.stopPropagation();
    this.notificationsService.markAsRead(n.id);
    const user = this.auth.currentUser;
    const role = user?.role;
    const reqId =
      n.linkRequestId?.trim() ||
      (n.actionRoute?.[0] === 'requests' && n.actionRoute?.[1] ? String(n.actionRoute[1]) : '') ||
      this.parseRequestIdFromMessage(n.message);

    if (reqId && (role === 'admin' || role === 'staff')) {
      void this.router.navigateByUrl(`/${role}/requests/${encodeURIComponent(reqId)}`);
    } else if (reqId && role === 'resident') {
      void this.router.navigateByUrl(`/resident/requests/${encodeURIComponent(reqId)}`);
    }

    this.closeNotifications();
    this.refreshNotifications();
  }

  private parseRequestIdFromMessage(message: string | undefined): string | undefined {
    if (!message) {
      return undefined;
    }
    const explicit = message.match(/\(Request #([^)]+)\)/);
    if (explicit) {
      return explicit[1].trim();
    }
    const hashForm = message.match(/request \(#([^)]+)\)/i);
    if (hashForm) {
      return hashForm[1].trim();
    }
    return undefined;
  }

  markAllAsRead() {
    for (const n of this.notifications) {
      if (!n.read) {
        this.notificationsService.markAsRead(n.id);
      }
    }
    this.refreshNotifications();
  }

  private refreshNotifications(): void {
    const user = this.auth.currentUser;
    this.notificationsService.setActivePortalUserId(user?.id ?? null);
    this.ensureFirestoreBellSubscription();
    const all = this.notificationsService.getNotificationsSnapshot();
    const residentBarangayId = this.auth.getResidentBarangayIdForNotifications();
    this.notifications = all.filter(n =>
      this.notificationsService.isVisibleToUser(
        n,
        user?.id ?? null,
        user?.role ?? null,
        residentBarangayId,
      ),
    );
    this.unreadCount = this.notifications.filter(n => !n.read).length;
  }

  /** Cross-device bell documents in Firestore (`portalNotifications`). */
  private ensureFirestoreBellSubscription(): void {
    const user = this.auth.currentUser;
    const role = (user?.role ?? '').toLowerCase();
    const barangay =
      role === 'resident'
        ? this.auth.getResidentBarangayIdForNotifications() ?? ''
        : '';
    const key = user
      ? role === 'resident'
        ? `${role}:${barangay}`
        : `${role}:${user.id}`
      : '';
    if (key === this.firestoreBellBindKey && this.firestorePortalSub && !this.firestorePortalSub.closed) {
      return;
    }
    this.firestoreBellBindKey = key;
    this.firestorePortalSub?.unsubscribe();
    if (!user) {
      this.notificationsService.applyFirestorePortalRows([]);
      return;
    }
    if (role === 'resident') {
      if (!barangay) {
        this.notificationsService.applyFirestorePortalRows([]);
        return;
      }
      this.firestorePortalSub = this.firestorePortal.observeResident(barangay).subscribe((rows: PortalNotificationRow[]) => {
        this.notificationsService.applyFirestorePortalRows(rows);
      });
      return;
    }
    if (role === 'admin' || role === 'staff') {
      const portalUserId = user.id;
      this.firestorePortalSub = this.firestorePortal
        .observeStaff(portalUserId)
        .subscribe((rows: PortalNotificationRow[]) => {
          this.notificationsService.applyFirestorePortalRows(rows);
        });
      return;
    }
    this.notificationsService.applyFirestorePortalRows([]);
  }

  private isNotFoundRouteSnapshot(route: ActivatedRouteSnapshot | null): boolean {
    if (!route) return false;

    // Check if this route itself is the 404 or wildcard route
    const cfg = route.routeConfig;
    if (cfg && (cfg.path === '404' || cfg.path === '**')) {
      // Only consider it a 404 if it's at the root level (no parent layout)
      // This means it's a truly unmatched route, not an invalid route within a layout
      const isRootLevel = !route.parent || route.parent.routeConfig === null;
      if (isRootLevel) {
        return true;
      }
    }

    // Recursively check children
    for (const child of route.children) {
      if (this.isNotFoundRouteSnapshot(child)) {
        return true;
      }
    }

    return false;
  }

  private updateGlobalUi(url: string) {
    const normalizedUrl = url.split('?')[0].split('#')[0];
    // Hide on login page, forgot password page, reset password page,
    // resident profile, request details page, 404 error page,
    // and the full-screen household map page (maximize map space).
    const isStaffOrAdminRequestDetailPage =
      /^\/(staff|admin)\/requests\/[^/]+\/?$/.test(normalizedUrl); // e.g. /staff/requests/1 or /admin/requests/1
    const isResidentProfilePage =
      /^\/(staff|admin)\/residents\/[^/]+\/?$/.test(normalizedUrl); // e.g. /staff/residents/1 or /admin/residents/1
    const isHouseholdMapPage =
      /^\/(staff|admin)\/households\/map/.test(normalizedUrl); // e.g. /staff/households/map or /admin/households/map
    const isHouseholdDetailPage =
      /^\/(staff|admin)\/households\/[^/]+\/?$/.test(normalizedUrl)
      && !normalizedUrl.includes('/households/map')
      && !normalizedUrl.includes('/households/add')
      && !normalizedUrl.includes('/edit');
    
    // Check if the currently activated route is the 404 / wildcard route
    const isNotFoundRoute = this.isNotFoundRouteSnapshot(this.router.routerState.snapshot.root);
    
    this.showGlobalUi = !normalizedUrl.startsWith('/login')
      && !normalizedUrl.startsWith('/contact')
      && !normalizedUrl.startsWith('/forgot-password')
      && !normalizedUrl.startsWith('/reset-password')
      && !normalizedUrl.includes('/residents/add')
      && !normalizedUrl.includes('/households/add')
      && !(normalizedUrl.includes('/households/') && normalizedUrl.includes('/edit'))
      && !isResidentProfilePage
      && !isStaffOrAdminRequestDetailPage
      && !isHouseholdMapPage
      && !isHouseholdDetailPage
      && !isNotFoundRoute;
    if (!this.showGlobalUi) this.showNotifications = false;
  }
}
